mapper.update:
update carsale_finance_plan
name = #{name}, down_payment_rate = #{downPaymentRate}, periods = #{periods}, interest_rate = #{interestRate}, status = #{status},
where id = #{id}

mapper.select:
select id, name, down_payment_rate, periods, interest_rate, status, create_time, update_time
from carsale_finance_plan

    and id = #{id}
    and name like concat('%', #{name}, '%')
    and down_payment_rate = #{downPaymentRate}
    and periods = #{periods}
    and interest_rate = #{interestRate}
    and status = #{status}

order by down_payment_rate, periods
